 I am developing a first person shooter. For my weapon animations, I use PID controllers to implement procedurally animated weapon sway. My goal is to make the weapon feel like it has mass and inertia when the player is moving, instead of being bolted to it's parent transform and moving without any delay or sway, which would feel very robotic and unsatisfying. 
 What I want to achieve is something like this: 

 The regulator class is implemented as follows: 
  namespace Animation
{
    [Serializable]
    public class PidController
    {
        public float P, I, D;

        private float _integral;
        private float _previousError;
        private bool _firstUpdate = true;

        public float Calculate(float targetValue, float currentValue, float deltaTime)
        {
            var error = targetValue - currentValue;
            var proportional = P * error;

            _integral += error * deltaTime;
            var integralTerm = I * _integral;

            var derivative = 0f;

            if (!_firstUpdate &amp;&amp; deltaTime &gt; 0f)
            {
                derivative = (error - _previousError) / deltaTime;
            }

            var derivativeTerm = D * derivative;

            _previousError = error;
            _firstUpdate = false;

            return proportional + integralTerm + derivativeTerm;
        }

        public void Reset()
        {
            _integral = 0;
            _previousError = 0;
            _firstUpdate = true;
        }
