  [AttributeUsage(AttributeTargets.Method)]
public class TimeMethodAttribute : OverrideMethodAspect
{
    private readonly string _timespanFormat;
    private readonly bool _formatSetInCtor;

    [IntroduceDependency]
    private readonly ILogger _logger;   // Assigned at runtime

    [IntroduceDependency]
    private readonly IConfiguration _configuration;

    public override dynamic? OverrideMethod()
    {
        var resolvedFormat = string.Empty;

        if (string.IsNullOrWhiteSpace(_timespanFormat))
        {
            var formatFromConfig = AspectHelper.GetTimeSpanFormatFromConfig(_configuration);
            resolvedFormat = AspectHelper.IsValidTimeSpanFormat(formatFromConfig, out _)
                ? formatFromConfig
                : AspectHelper.DefaultTimeSpanFormatString;
        }

        var sw = new Stopwatch();
        sw.Start();
        var result = meta.Proceed();
        sw.Stop();

        _logger.Debug(&quot;Method {$MethodName} Execution Time {$ExecutionTime}&quot;, meta.Target.Method.Name, sw.Elapsed.ToString(resolvedFormat));
        return result;
    }
}

