function getTopAverage(array: number[], percentile: number, upper: boolean) {
  if (array.length == 0) {return 0;}
  let sortedArray = array.toSorted((a, b) =&gt; a - b)

  if (upper) {sortedArray = sortedArray.reverse()}

  let numbersToChoose = Math.ceil((percentile / 100) * sortedArray.length)
  sortedArray = sortedArray.slice(0,numbersToChoose)

  return sortedArray.reduce((sum, x) =&gt; sum + x) / sortedArray.length
}

